import React, { useState, useEffect } from 'react';
import SplashScreen from './components/SplashScreen';
import Register from './components/Register';
import Chat from './components/Chat';
import { askPermission, getPushToken, listenMessages } from './services/notifications';

function App() {
  const [showSplash, setShowSplash] = useState(true);
  const [userId, setUserId] = useState('');
  const [username, setUsername] = useState('');
  const [isAuth, setIsAuth] = useState(false);
  
  useEffect(() => {
    const savedId = localStorage.getItem('userId');
    const savedName = localStorage.getItem('username');
    
    if (savedId && savedName) {
      setUserId(savedId);
      setUsername(savedName);
      setIsAuth(true);
      setupNotifications();
    }
  }, []);
  
  const setupNotifications = async () => {
    const granted = await askPermission();
    if (granted) {
      await getPushToken();
      if (userId) {
        listenMessages(userId);
      }
    }
  };
  
  const handleRegister = async (id: string, name: string) => {
    setUserId(id);
    setUsername(name);
    setIsAuth(true);
    const granted = await askPermission();
    if (granted) {
      await getPushToken();
      listenMessages(id);
    }
  };
  
  if (showSplash) return <SplashScreen onComplete={() => setShowSplash(false)} />;
  if (!isAuth) return <Register onRegister={handleRegister} />;
  return <Chat userId={userId} username={username} />;
}

export default App;