import { getMessaging, getToken, onMessage } from 'firebase/messaging';
import { db } from '../firebase';
import { ref, set } from 'firebase/database';

const VAPID_KEY = 'BGdcfaL37a8w6EDc55GBH_nQLZ0w6zEEQzYnIX9yQiriXhsevuwmW3qYzoCIIUONC1-nViDEFCMjiPol4dQJj0k'; // ТВОЙ КЛЮЧ

// Запрос разрешения
export const askPermission = async () => {
  const result = await Notification.requestPermission();
  return result === 'granted';
};

// Получение токена
export const getPushToken = async () => {
  try {
    const messaging = getMessaging();
    const token = await getToken(messaging, { vapidKey: VAPID_KEY });
    
    if (token) {
      const userId = localStorage.getItem('userId');
      if (userId) {
        await set(ref(db, `users/${userId}/fcmToken`), token);
      }
      console.log('✅ Токен получен:', token);
      return token;
    }
  } catch (error) {
    console.error('❌ Ошибка токена:', error);
  }
  return null;
};

// Показать уведомление
export const showNotification = (title: string, body: string) => {
  if (Notification.permission === 'granted') {
    new Notification(title, { body, icon: '/logo192.png' });
  }
};

// Слушаем новые сообщения
export const listenMessages = (currentUserId: string) => {
  import('firebase/database').then(({ ref, onChildAdded }) => {
    const messagesRef = ref(db, 'messages');
    
    onChildAdded(messagesRef, (snapshot) => {
      const msg = snapshot.val();
      if (msg.senderId !== currentUserId) {
        showNotification(`📱 ${msg.senderName}`, msg.text || 'Отправил фото');
      }
    });
  });
};